import { useAuth } from "../hooks/useAuth";
import { ENDPOINTS } from '../app/config/config.js';

const trackEvent = (eventName = {}) => {
  try{
    const { user } = JSON.parse(localStorage.getItem('user')) 

    console.log("Analytics Event:", eventName, user); // Debugging (Remove in production)
    let version = localStorage.getItem('appVersion');
    // Example: Send data to an analytics provider (Supabase, Google Analytics, Mixpanel, etc.)
    fetch(ENDPOINTS.Events, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ eventName: version +"_"+ eventName, username:user , timestamp: new Date().toISOString() }),
    });
  }catch(error) {

  }

  };
  
  export default trackEvent;
  